    if len(bars) < 1:
        return out
    bar = max(bars)
    top_row = next((r for r in range(h) if sum(v == 5 for v in grid[r]) >= 2), 1)
    left_edge = max((c for c, v in enumerate(grid[top_row]) if v == 5 and c < bar), default=0)
    for r in range(1, h-1):
        left = next((grid[r][c] for c in range(left_edge+1) if grid[r][c] not in (0,5)), 0)
        if left:
            for c in range(left_edge+1):
                if grid[r][c] == 0: out[r][c] = left
    # The two-row color strip below the bar tiles upward on its right side.
    seeds = [r for r in range(h) if any(grid[r][c] not in (0,5) for c in range(bar+1,w))]
    if seeds:
        top_seed, bottom_seed = seeds[0], seeds[-1]
        if bottom_seed-top_seed == 1:
            for r in range(1, bottom_seed):
                source = bottom_seed if (bottom_seed-r)%2 == 0 else top_seed
                for c in range(bar+1,w):
                    if grid[source][c] not in (0,5): out[r][c] = grid[source][c]
    return out

