    hbars = [r for r in range(h) if sum(x == 5 for x in grid[r]) >= 3]
    vbars = [c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) >= 3]
    for r in hbars:
        cols = [c for c,x in enumerate(grid[r]) if x == 5]
        lo, hi = min(cols), max(cols)
        seed_cols = [c for c in range(lo, hi+1) if grid[r][c] == 5]
        # contiguous bar; colored column immediately beneath/above it seeds rows
        for c in seed_cols:
            vals = [grid[y][c] for y in range(h) if grid[y][c] not in (0,5)]
            if vals:
                first = next(y for y in range(h) if grid[y][c] not in (0,5))
                last = max(y for y in range(h) if grid[y][c] not in (0,5))
                for y in range(first,last+1):
                    if grid[y][c] not in (0,5):
                        for x in range(lo,hi+1):
                            if grid[y][x] == 0: out[y][x] = grid[y][c]
